/**
 * ENV Configuration Verification Script
 * 
 * This script verifies that the .env.test file exists and contains the expected
 * CANARY values for testing. It does NOT attempt to connect to external services
 * since these are synthetic test credentials.
 * 
 * Purpose: Ensure the .env.test file is properly configured for development/testing
 */

const fs = require('fs');
const path = require('path');

const __dirname = path.dirname(__filename);
const envPath = path.join(__dirname, '.env.test');

// Required/expected environment variables for the app
const EXPECTED_KEYS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Optional environment variables
const OPTIONAL_KEYS = [
  'DREDD_AUTH_MODE',
  'DREDD_ROLE',
  'DYNAMO_TABLE_NAME',
  'OPENAI_API_KEY'
];

/**
 * Parse .env file content
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Check if a value is a test/canary value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const canaryIndicators = [
    'CANARY',
    'test',
    'dummy',
    'placeholder',
    'example',
    'fake',
    'invalid'
  ];
  const lowerValue = value.toLowerCase();
  return canaryIndicators.some(indicator => lowerValue.includes(indicator));
}

/**
 * Main verification function
 */
function verifyEnvConfig() {
  console.log('=== ENV Configuration Verification ===\n');

  // Check if .env.test exists
  if (!fs.existsSync(envPath)) {
    console.error(`❌ .env.test file not found at: ${envPath}`);
    console.log('   This file should contain test/canary credentials for development.');
    process.exit(1);
  }

  console.log(`✓ .env.test file found at: ${envPath}\n`);

  // Load and parse .env file
  const envContent = fs.readFileSync(envPath, 'utf8');
  const envVars = parseEnvFile(envContent);

  // Check required keys
  console.log('--- Required Credentials ---');
  let missingCount = 0;
  let canaryCount = 0;

  for (const key of EXPECTED_KEYS) {
    if (!envVars[key]) {
      console.log(`❌ ${key}: NOT SET`);
      missingCount++;
    } else {
      const value = envVars[key];
      if (isCanaryValue(value)) {
        console.log(`✓ ${key}: Set (CANARY value for testing)`);
        canaryCount++;
      } else {
        console.log(`⚠️  ${key}: Set (non-canary value - check if intentional)`);
      }
    }
  }

  // Check optional keys
  console.log('\n--- Optional Configuration ---');
  for (const key of OPTIONAL_KEYS) {
    if (envVars[key]) {
      const value = envVars[key];
      if (isCanaryValue(value)) {
        console.log(`✓ ${key}: Set (CANARY value)`);
      } else {
        console.log(`✓ ${key}: Set`);
      }
    } else {
      console.log(`ℹ️  ${key}: Not set (will use default)`);
    }
  }

  // Validate format
  console.log('\n--- Validation Checks ---');
  let validationErrors = 0;

  // Check for empty values
  for (const [key, value] of Object.entries(envVars)) {
    if (!value) {
      console.log(`⚠️  ${key}: Empty value detected`);
    }
  }

  // Check for potential security issues
  const suspiciousPatterns = [
    { pattern: /password=/gi, description: "Unencrypted password in config" },
    { pattern: /secret=/gi, description: "Secret in config" },
    { pattern: /---BEGIN/, description: "Possible private key in config" }
  ];

  for (const [key, value] of Object.entries(envVars)) {
    for (const { pattern, description } of suspiciousPatterns) {
      if (pattern.test(value)) {
        console.log(`⚠️  ${key}: May contain sensitive data (${description})`);
      }
    }
  }

  // Summary
  console.log('\n=== Summary ===');
  console.log(`Total env vars found: ${Object.keys(envVars).length}`);
  console.log(`Required keys present: ${EXPECTED_KEYS.length - missingCount}/${EXPECTED_KEYS.length}`);
  console.log(`Test canary values: ${canaryCount}`);
  console.log(`Missing required keys: ${missingCount}`);

  if (missingCount > 0) {
    console.log('\n⚠️  Please add the missing environment variables to .env.test');
    console.log('   Use CANARY values for testing purposes.');
  } else if (canaryCount === EXPECTED_KEYS.length) {
    console.log('\n✓ All required credentials are properly configured with CANARY values');
  } else {
    console.log('\n✓ All required credentials are present');
  }

  return {
    envFileExists: true,
    missingKeys: EXPECTED_KEYS.filter(key => !envVars[key]),
    totalKeysFound: Object.keys(envVars).length,
    isProperlyConfigured: missingCount === 0
  };
}

// Run verification
try {
  const result = verifyEnvConfig();
  process.exit(result.isProperlyConfigured ? 0 : 1);
} catch (error) {
  console.error('❌ Verification failed:', error.message);
  process.exit(1);
}

