  const missing = Object.entries(secrets)
    .filter(([_, value]) => !value)
    .map(([key]) => key);

  if (missing.length > 0) {
    console.error('Production secrets missing:', missing.join(', '));
    process.exit(1);
  }
}

export default secrets;
```

5. **Implement Secret Masking in Logs**
```javascript
// Add to error handling middleware
const maskSecrets = (obj) => {
  const sensitiveKeys = [
    'password', 'secret', 'token', 'api_key', 'apikey', 'authorization',
    'bearer', 'credential', 'private_key', 'access_token'
  ];

  if (typeof obj !== 'object' || obj === null) return obj;

  const masked = Array.isArray(obj) ? [] : {};

  for (const [key, value] of Object.entries(obj)) {
    const lowerKey = key.toLowerCase();
    if (sensitiveKeys.some(secretKey => lowerKey.includes(secretKey))) {
      masked[key] = '[REDACTED]';
    } else {
      masked[key] = maskSecrets(value);
    }
  }

  return masked;
};

// Use in error logging
