        return false;
      }

      const result = await runCommand('psql', [url, '-c', 'SELECT 1'], 5000);

      if (result.timedOut) {
        console.log('❌ Database connection timed out');
        return false;
      }

      if (result.code === 0 && result.output.includes('1')) {
        console.log('✓ Database connection successful (psql)');
